CREATE OR REPLACE FUNCTION public.log_audit_event(p_action text, p_target_type text, p_target_id text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_user_email text;
  v_user_role text;
  v_log_id uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is not null then
    select email into v_user_email from auth.users where id = v_user_id;
    select coalesce(role, 'student') into v_user_role from public.profiles where id = v_user_id;
  end if;
  
  insert into public.audit_logs (
    actor_id,
    actor_email,
    actor_role,
    action,
    target_type,
    target_id,
    details
  ) values (
    v_user_id,
    v_user_email,
    coalesce(v_user_role, 'unknown'),
    p_action,
    p_target_type,
    p_target_id,
    p_details
  ) returning id into v_log_id;

  return v_log_id;
end;
$function$
